            value = func(*args, **kwargs)

            if lock is not None: # We use the ``lock`` parameter to synchronize access to the cache.
                with lock:
                    cache[cache_key] = value
            else:
                cache[cache_key] = value

            return value

        return wrapped

    return wrapper

