def hashkey(func, args, kwargs):
    return hashlib.md5((func.__name__ + '|'.join(map(str, args)) + '|'.join(f'{k}={v}' for k, v in kwargs.items())).encode('utf-8')).hexdigest()

def extostr(cls, e, max_level=30, max_path_level=5):
    if max_level <= 0:
        return '<Exception: message="...message...">'

    exc_info = sys.exc_info()
    if exc_info[0] == e.__class__:
        exc_traceback = exc_info[2]
        if not exc_traceback or not exc_traceback.tb_frame:
            return '<Exception: message="...message...">'

        levels = []
        for _ in range(max_level):
            tb = exc_traceback
            filename, line_number, function_name, text = traceback.extract_tb(exc_traceback)[-1]
            if max_path_level > 0:
                filename = os.path.relpath(filename, start=os.getcwd())
            levels.append((filename, line_number, function_name, text))
            exc_traceback = tb.tb_next
        return 'Exception: message="%s"\n%s' % (str(e), '\n'.join('    %s:%d %s: %s' % (filename, line_number, function_name, text) for filename, line_number, function_name, text in levels))
    else:
        return '<%s: message="...">' % (e.__class__.__name__)

