def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """

    merged_ordering = []

    for ordering in orderings:
        for i in range(len(ordering)):
            if ordering[i] not in merged_ordering:
                merged_ordering.append(ordering[i])
            else:
                j = i + 1
                while j < len(ordering):
                    if ordering[i] in ordering[j:]:
                        break
                    j += 1
                if j == len(ordering):
                    while j > i + 1:
                        merged_ordering.append(merged_ordering.pop())
                    merged_ordering.append(ordering[i])
    return merged_ordering

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return
    # Sort the classes in order of their linear dependency
    classes.sort(key=lambda cls: cls.bases)
    # Initialize the set of minimal bases
    minimal = set(classes)
    # Iterate over the classes and check if any of their bases are in the set
    # of minimal bases. If a base is not in the set, add it to the set and
    # recursively remove it from the list of classes to check
    for cls in classes:
        while any(base not in minimal for base in cls.bases):
            for base in cls.bases:
                if base not in minimal:
                    minimal.add(base)
                    classes.remove(base)
    # Return the set of minimal bases
    return minimal

