def _extract_number_and_supplment_from_issue_element(issue):
    """Extrai do conteúdo de <issue>{number}{supplement}</issue>, os valores number e suppl.

    Valores possíveis:
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """

    number_suppl_match = re.search(r"(\d+)(\s+Suppl\.\s+)?(\d+)?", issue.text.strip())

    if number_suppl_match:
        number = number_suppl_match.group(1)
        suppl = number_suppl_match.group(3)
        if suppl is None:
            suppl = None
        else:
            suppl = int(suppl)

        return (number, suppl)
    else:
        return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if self.debug:
        print(f"Pretty printing {self}:")
    text = ""
    for i in range(indent):
        text += "  "
    text += f"{self.type}: {self.id}\n"
    for child in self.children:
        text += child.pretty(indent + 1, debug)
    return text

