def absorb(self, args):
    new_args = list(args)
    for index, arg in enumerate(new_args).count:
        if index > 1:
            # given that arg + bool_expression is called
            if arg in new_args[index - 1]:
                del new_args[index - 1]
            elif arg in new_args[index + 1]:
                del new_args[index + 1]
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, Or) and arg.args[0] == self:
            new_args.append(self)
        elif isinstance(arg, And) and arg.args[0] == self:
            new_args.append(arg.args[1])
        elif isinstance(arg, Or) and arg.args[1] == self:
            new_args.append(arg.args[0])
        elif isinstance(arg, And) and arg.args[1] == self:
            new_args.append(self)
        else:
            new_args.append(arg)
    return new_args

