def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Split the commands into individual commands
    cmd = commands.split()

    # Create a list of arguments for each command
    arglist = [args.split()]

    # If any arguments are given as a list of lists, flatten them
    for i in range(len(arglist)):
        if type(arglist[i]) is list:
            arglist[i] = list(chain.from_iterable(arglist[i]))

    # Create the full argument list for each command
    full_args = []
    for i in range(len(cmd)):
        full_args.extend(arglist[i])

    # Execute the command and get the return code
    rc = 0
    for i in range(len(cmd)):
        rc = subprocess.call([cmd[i]] + full_args[i], cwd=cwd, env=env)

    # Check the return code and raise an error if necessary
    if rc != 0:
        if verbose:
            logger.warning("Command returned non-zero exit status ({}).".format(rc))
        else:
            logger.warning("Command returned non-zero exit status ({}). Use --verbose to see full output.".format(rc))
        if hide_stderr:
            raise CommandError("Command returned non-zero exit status ({}).".format(rc))
        else:
            raise CommandError("Command returned non-zero exit status ({}). Use --hide-stderr to hide full output.".format(rc))

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    Arguments:
        commands (list): A list of commands to execute. Each command is a list of arguments, where the first element is the command itself and the remaining elements are its arguments.
        args (list): The arguments to pass to the command.
        cwd (str, optional): The working directory to set before executing the command.
        verbose (bool, optional): Whether to print the command and its output to the console.
        hide_stderr (bool, optional): Whether to hide the error output of the command.
        env (dict, optional): A dictionary of environment variables to set before executing the command.
    """

    if not isinstance(commands, list):
        commands = [commands]

    for command in commands:
        if not isinstance(command, list):
            command = [command]

        if not cwd:
            cwd = os.getcwd()

        try:
            proc = subprocess.Popen(command + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except FileNotFoundError as e:
            raise CommandNotFoundError(f"{command[0]} not found in PATH. Make sure it is installed and in the PATH.") from e

        (out, err) = proc.communicate()

        if verbose:
            print(f"$ {command[0]} {' '.join(command[1:])}\n")

        out_str = out.decode("utf-8")
        out_lines = out_str.splitlines()

        if verbose:
            for line in out_lines:
                print(line)

        err_str = err.decode("utf-8")
        err_lines = err_str.splitlines()

        if hide_stderr:
            err_lines = []

        if err_lines and verbose:
            for line in err_lines:
                print(f"** {line}", file=sys.stderr)

    return out_lines

