    import subprocess
    import sys
    import shlex

    if env is not None:
        env = {**os.environ, **env}

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    for command in commands:
        if verbose:
            print('Running command: "%s"' % ' '.join(command))

        try:
            proc = subprocess.Popen(command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=(subprocess.PIPE if not hide_stderr else None))
            out, err = proc.communicate()
            retcode = proc.returncode
            success = retcode == 0
        except:
            print('Error running command: %s' % ' '.join(command))
            raise

        if verbose and out:
            print('Command output:')
            print(out.decode('utf-8'))
        if verbose and err:
            print('Command error output:')
