def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Args:
        validate_objects (bool, optional): Whether to validate individual objects. Defaults to True.
        check_digests (bool, optional): Whether to check digests of objects. Defaults to True.
        show_warnings (bool, optional): Whether to show warnings. Defaults to False.

    Returns:
        num_objects (int): Number of objects checked
        good_objects (int): Number of objects checked that were found to be valid

    Raises:
        ValueError: If the storage root is not valid
    """
    num_objects = 0
    good_objects = 0

    if not self.validate():
        raise ValueError("Storage root is not valid")

    # validate object nodes
    if validate_objects:
        for node in self.object_nodes:
            num_objects += 1
            if node.validate(digests=check_digests):
                good_objects += 1
            elif show_warnings:
                logger.warning(f"Object node {node.id} is not valid")

    # validate label nodes
    if validate_objects:
        for node in self.label_nodes:
            num_objects += 1
            if node.validate(digests=check_digests):
                good_objects += 1
            elif show_warnings:
                logger.warning(f"Label node {node.id} is not valid")

    return num_objects, good_objects

