    if check_digests:
        for obj in self.iterobjects:
            num_objects += 1
            if obj.digest == obj.calculate_digest():
                good_objects += 1
            else:
                if show_warnings:
                    print("Warning: Invalid digest for object", obj)

    # return number of objects checked and number of valid objects
    return num_objects, good_objects

