    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.isdigit():
        next_version = str(int(version) + 1)
    else:
        next_version = "1"
    return next_version

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version.isdigit():
        return str(int(version) + 1).zfill(len(version))
    else:
        # non-zero prefixed version
        return version[:-1] + str(int(version[-1]) + 1)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Get the root inventory and content digests
    root_inventory = self.get_inventory_at(0)
    root_digests = { f.id: f.content_digest for f in root_inventory }

    # Iterate through the versions
    for version_dir in version_dirs:
        # Get the inventory for this version
        inventory = self.get_inventory_at(version_dir)
        # Get the content digests for this version
        digests = { f.id: f.content_digest for f in inventory }

        # Check that all files have inventory entries
        for f in inventory:
            if f.id not in root_digests:
                raise Exception(f"Version {version_dir} missing inventory entry for file {f.id}")

        # Check that the content digests match the root inventory
        for id, digest in digests.items():
            if id not in root_digests or digest != root_digests[id]:
                raise Exception(f"Version {version_dir} has incorrect content digest for file {id}")

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_digests = self.get_content_digests()
    for version in version_dirs:
        if not self.get_content_digests(version=version):
            raise ValidationError(f"Missing inventory for version {version}")
        for digest in self.get_content_digests(version=version):
            if digest not in root_digests:
                self.different_digests.append(digest)

