    Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = self.get_inventory()
    root_digests = {}
    for di in root_inventory['digests']:
        root_digests[di['path']] = di['sha256']

    for version_dir in version_dirs:
        version_inventory = self.get_inventory_by_version(version_dir)
        for di in version_inventory['digests']:
            path = di['path']
            if path in root_digests:
                if root_digests[path] != di['sha256']:
                    raise InvalidInventoryError(
                        f"Content digest for {path} in version {version_dir} "
                        f"is different from the one in the root inventory"
                    )
            else:
                root_digests[path] = di['sha256']

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        with open(os.path.join(path, "0=*.namaste"), "r") as namaste_file:
            lines = namaste_file.readlines()
            if Path("ocfl_object").lower() in lines[0].lower():
                return 'object'
            elif Path("storage_root").lower() in lines[0].lower():
                return 'root'
            else:
                return 'file'
    except (FileNotFoundError, isolationlib.errors.MissingMetafileError):
        return 'file'
    except Exception as e:
        return 'error: {}'.format(str(e))

