def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    env_var_name = matcher.group(1)
    default_value = matcher.group(3)

    if default_value:
        default_value = default_value.strip('"')

    value = os.getenv(env_var_name)
    if value is None and default_value is None:
        raise RuntimeError(f"Environment variable {env_var_name} is not defined")
    elif value is not None:
        return value
    else:
        return default_value

def get_env_val(matcher):
    '''
    Parse a matcher that contains a name and an optional default value for an environment variable.
    If the variable is not defined in the environment and no default value is provided, raise an Exception.

    Args:
        matcher (str or tuple): The matcher to parse. Can be in the form of a string or a tuple.

    Returns:
        str: The value of the environment variable if found, else the default value.

    Raises:
        EnvironmentError: If the variable is not defined in the environment and no default value is provided.
    '''

    if isinstance(matcher, str):
        return os.getenv(matcher)
    elif isinstance(matcher, tuple):
        name, default = matcher[0], matcher[1]
        val = os.getenv(name)
        if val is None:
            if default is None:
                raise EnvironmentError(f"Environment variable {name} not found and no default value provided.")
            else:
                return default
        else:
            return val

