def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Create a list of all the commands to be run
    if isinstance(commands, str):
        commands = [commands]
    if isinstance(args, str):
        args = [args]
    if isinstance(cwd, str):
        cwd = [cwd]
    # Check that the commands and arguments are valid
    if not isinstance(commands, list) or not isinstance(args, list) or not isinstance(cwd, list):
        raise ValueError("commands, args, and cwd must be lists")
    if len(commands) != len(args) or len(commands) != len(cwd):
        raise ValueError("commands, args, and cwd must be the same length")
    # Build the list of subprocess arguments
    subargs = []
    for command, arg in zip(commands, args):
        if not isinstance(command, str):
            raise ValueError("commands must be a list of strings")
        if not isinstance(arg, list):
            raise ValueError("args must be a list of lists")
        subargs.append([command] + arg)
    # Run the commands
    for subarg in subargs:
        try:
            subprocess.run(subarg, cwd=cwd, verbose=verbose, hide_stderr=hide_stderr, env=env)
        except subprocess.CalledProcessError as e:
            raise e
    return None

