def find_roots(graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if not roots:
        roots = set()

    for s, p, o in graph:
        if p == prop and o in roots:
            roots.add(s)

    for root in roots:
        find_roots(graph, prop, {root})

    return roots

def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    if roots is None:
        roots = set()
    for child, parent in graph.subject_objects(prop):
        if child in roots:
            continue
        if not any(parent in roots for parent in graph.subject_objects(prop)):
            roots.add(child)
    return roots

def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """

    # Create a set to store the roots
    if roots is None:
        roots = set()

    # Iterate over the graph and add nodes to the set
    for s, p, o in graph:
        if p == prop:
            roots.add(o)

    # Recursively add the parents of the roots
    for root in roots:
        for s, p, o in graph.triples((root, prop, None)):
            roots.add(o)
            roots = find_roots(graph, prop, roots)

