def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    result = {}
    if 'XRD' in document:
        # Parse XRD format
        root = ElementTree.fromstring(document)
        for link in root.findall('.//{http://cloud.github.com/schemas/latest/xrd.json}Link'):
            rel = link.attrib.get('rel')
            if rel == 'http://buzzword.org.uk/2009/atom-entries#index-ref':
                result['atom-entries'] = link.attrib.get('href')
            elif rel == 'http://buzzword.org.uk/2009/atom-entries#self-ref':
                result['atom-entries-self'] = link.attrib.get('href')
        for link in root.findall('.//{http://buzzword.org.uk/2009/atom-entries#self-ref}Link'):
            result['atom-entries-self'] = link.attrib.get('href')
        for link in root.findall('.//{http://buzzword.org.uk/2009/atom-entries#index-ref}Link'):
            result['atom-entries'] = link.attrib.get('href')
        for link in root.findall('.//{http://purl.org/xrd/xrd-1.0/}Property'):
            result[link.attrib.get('property')] = link.text
        for link in root.findall('.//{http://purl.org/xrd/xrd-1.0/}Category'):
            result[link.attrib.get('scheme')] = link.attrib.get('label')
    else:
        # Parse JSON format
        result = json.loads(document)

    return result

