def retrieve_and_parse_diaspora_webfinger(handle):
    """Retrieve and parse a remote Diaspora webfinger document.

    Args:
        handle: Remote handle to retrieve

    Returns:
        dict: parsed webfinger data
    """"""
    import requests
    from xml.etree import ElementTree

    r = requests.get(handle, headers={"Content-Type": "application/xrd+xml"})
    if r.status_code == 200:
        xml = r.content
        tree = ElementTree.fromstring(xml)
        webfinger = {}
        for el in tree:
            if el.tag == "Subject":
                webfinger["handle"] = el.text
            elif el.tag == "Property":
                if el.attrib["type"] == "http://diaspora.xsede.org/ns/hosted":
                    webfinger["host"] = el.attrib["val"]
                elif el.attrib["type"] == "http://diaspora.xsede.org/ns/port":
                    webfinger["port"] = int(el.attrib["val"])
                elif el.attrib["type"] == "http://diaspora.xsede.org/ns/ssl":
                    webfinger["ssl"] = (el.attrib["val"] == "true")
                elif el.attrib["type"] == "http://diaspora.xsede.org/ns/protocol":
                    webfinger["protocol"] = el.attrib["val"]
        return webfinger
    else:
        raise Exception("Error retrieving webfinger document for handle {}".format(handle))

