    This method is intended to be used to resolve default argument values for a function or method based on the definition in the spec and any other relevant sources.
    """
    # Loop through the function's parameters and check if default values are defined in the spec
    for param in self.spec.get("parameters", []):
        if "defaultValue" in param:
            # If a default value is defined, attempt to resolve it
            try:
                param["default"] = self.resolve_default_value(param["defaultValue"])
            except Exception as e:
                # If an error occurs, log a warning and continue with the next parameter
                LOGGER.warning(f"Unable to resolve default value for parameter {param['name']}: {e}")
                continue
        else:
            # If no default value is defined, set the parameter's default value to None
            param["default"] = None

    # Return the resolved defaults
    return {param["name"]: param["default"] for param in self.spec.get("parameters", [])}

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    This method is used to determine the default values for the argument of a function
    based on the information provided in its specification.

    Returns:
        A dictionary containing the default values for the arguments of the method.
    """
    spec = self.get_spec()
    defaults = {}
    for arg_name, arg in spec.args.items():
        if arg.default is not None:
            defaults[arg_name] = arg.default
        elif arg.annotation is not None:
            defaults[arg_name] = arg.annotation
        else:
            defaults[arg_name] = arg.empty
    return defaults

