def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = dict()
    for arg in vars(self):
        if arg.startswith('_') or arg == 'action':
            continue
        # check if argument is deprecated by looking for a 'deprecated_' prefix
        if arg.startswith('deprecated_') and vars(self)[arg]:
            # use the attribute name without prefix as key for the dict
            deprecated_args[arg.split('deprecated_')[1]] = vars(self)[arg]
    return deprecated_args

