    deprecated_args = []
    for arg in cli_args:
        if cli_args[arg] and arg in answer_file_args:
            deprecated_args.append(arg)
    if deprecated_args:
        msg = ("The following arguments are deprecated and have been overridden by arguments "
               "from the answer file: {}.").format(", ".join(deprecated_args))
        print(msg, file=sys.stderr)
    return cli_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    # Check for deprecated arguments
    for dep_arg in self.deprecated_args():
        if dep_arg in cli_args:
            self.warning(f"Argument '{dep_arg}' is deprecated"
                         " and has been replaced by a new one. Please use '{self.new_arg}' instead.")
        if dep_arg in answer_file_args:
            self.warning(f"Argument '{dep_arg}' is decomissioned"
                         " in the latest version and should not be used in answer files.")

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args: the dict of arguments from files
    """

    # get a list of deprecated arguments from the help message
    deprecated_args = self.parser._option_string_actions

    # validate each argument
    for arg in cli_args:
        if arg in deprecated_args:
            print(f"WARNING: {arg} argument is deprecated and will be removed in the future. Please use the replacement argument.")

    for arg in answer_file_args:
        if arg in deprecated_args:
            print(f"WARNING: {arg} argument is deprecated and will be removed in the future. Please use the replacement argument.")

