def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                            spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """

        if spec_option['format'] == 'enum':
            return self.create_enum_complex_argumet_type(
                subcommand, type_name, option_name, spec_option['enum_options']
            )
        elif spec_option['format'] == 'class':
            return self.create_class_complex_argumet_type(
                subcommand, type_name, option_name, spec_option['class_options']
            )
        elif spec_option['format'] == 'resource':
            return self.create_resource_complex_argumet_type(
                subcommand, type_name, option_name, spec_option
            )
        else:
            raise TypeError(f"Unsupported argument format: {spec_option['format']}")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    if not args:
        return control_args, nested_args
    for arg_name, arg_value in args.items():
        if arg_name in self.control_args:
            control_args[arg_name] = arg_value
        else:
            nested_args[arg_name] = arg_value
    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Return nested and custom arguments.
    :param args (dict): collected list of args
    :return: tuple(control_args (dict), nested_args (dict))
    """
    # Initialize nested and custom arg dicts
    nested_args = {}
    custom_args = {}
    for arg in args:
        # Add each arg to the appropriate dict based on its type
        if arg['type'] == 'nested':
            nested_args[arg['name']] = arg['value']
        elif arg['type'] == 'custom':
            custom_args[arg['name']] = arg['value']
    return custom_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        # treat control args differently
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg in AnsibleParameter.NESTED_ARGS:
            nested_args[arg] = args[arg]
        else:
            custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith("_"):
            control_args[arg[1:]] = None
        elif arg.startswith("~"):
            nested_args[arg[1:]] = None
        elif arg.startswith("{"):
            custom_args[arg[1:]] = None
        else:
            nested_args[arg] = None

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars is not None:
        for k, v in extra_vars.items():
            if k in vars_dict:
                raise ValueError(f"Found duplicate key {k} in vars_dict")
            vars_dict[k] = v
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        extra_vars = []
    for var in extra_vars:
        vars_dict[var] = vars_dict.get(var, [])
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars:
        for var in extra_vars:
            if not vars_dict.get(var):
                vars_dict[var] = {}
            merge_extra_vars(vars_dict[var], extra_vars)
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    if extra_vars:
        for var in extra_vars:
            if var not in vars_dict:
                vars_dict[var] = []
            else:
                if not isinstance(vars_dict[var], list):
                    vars_dict[var] = [vars_dict[var]]
            vars_dict[var].extend(extra_vars[var])

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return

    for var in extra_vars:
        if var in vars_dict:
            raise ValueError(f"Cannot merge extra-vars: {var} already exists in {vars_dict}")
        else:
            vars_dict[var] = var

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):

    # Set up the working directory
    workdir = os.path.join(ir_workspace.workspace_path, 'ansible')
    if not os.path.exists(workdir):
        os.makedirs(workdir)
    os.chdir(workdir)

    # Prepare the ansible-playbook command
    cmd = ['ansible-playbook', '-i', 'localhost', playbook_path]
    if verbose is not None:
        cmd.append('-' + verbose)
    if extra_vars:
        cmd.extend(['-e', json.dumps(extra_vars)])
    if ansible_args:
        cmd.extend(ansible_args)

    # Call the ansible-playbook script
    proc = Popen(cmd, stdout=PIPE, stderr=PIPE)
    out, err = proc.communicate()
    retcode = proc.returncode
    if retcode != 0:
        # Handle ansible-playbook errors
        msg = ''
        if out:
            msg += 'Output:\n' + out.decode()
        if err:
            msg += 'Error:\n' + err.decode()
        raise AnsibleExecutionFailed(msg, retcode=retcode)

    # Return the results
    return out.decode()

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
    workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    """
    command = ['ansible-playbook', str(playbook_path)]
    if verbose:
        command.append('--' + verbose)
    if extra_vars:
        if isinstance(extra_vars, dict):
            for k, v in extra_vars.items():
                command.append('--extra-vars')
                command.append(f'"{k}={v}"')
        elif isinstance(extra_vars, str):
            command.append('--extra-vars')
            command.append(extra_vars)
        else:
            raise ValueError(f'Invalid value for extra_vars: {extra_vars}')
    if ansible_args:
        for k, v in ansible_args.items():
            command.append(k)
            command.append(v)
    print(ir_plugin.run_command(command, ir_workspace))

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    for arg, value in values_dict.items():
        if arg in self.cli_arguments and self.cli_arguments[arg].type in [int, float]:
            try:
                values_dict[arg] = self.cli_arguments[arg].type(value)
            except (ValueError, TypeError):
                raise InvalidArgumentError(self.cli_arguments[arg].name, value)
        elif arg in self.cli_arguments and self.cli_arguments[arg].accept_None:
            if value.lower() in [b'none', b'null', b'not set']:
                values_dict[arg] = None
        elif arg in self.cli_arguments and self.cli_arguments[arg].choices:
            if value.lower() in [b'none', b'null', b'not set']:
                values_dict[arg] = None
            else:
                values_dict[arg] = value.lower()
        elif arg in self.cli_arguments and self.cli_arguments[arg].type == bool:
            if value.isdigit():
                values_dict[arg] = bool(int(value))
            else:
                values_dict[arg] = value.lower() == b'true'
        elif arg in self.cli_arguments and self.cli_arguments[arg].type == list:
            for item in value.split(b','):
                values_dict[arg].append(item.strip())
        elif arg in self.cli_arguments and self.cli_arguments[arg].type == dict:
            values_dict[arg] = json.loads(value)
        else:
            values_dict[arg] = value.decode()

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        if parser_name == "main":
            if key == "input_file":
                values_dict[key] = str(os.path.abspath(value))
            if key == "output_file":
                values_dict[key] = str(os.path.abspath(value))
        elif parser_name == "virsh":
            if key == "id":
                values_dict[key] = int(value)
        elif parser_name == "ospd":
            if key == "tag":
                values_dict[key] = int(value)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = None
    with open(os.path.join(plugin_dir, "plugin.yaml"), "r") as f:
        plugin_spec = yaml.load(f, Loader=yaml.Loader)

    flatten_dict = {}
    for prop in plugin_spec["properties"]:
        if "value" in prop:
            flatten_dict[prop["id"]] = prop["value"]
        elif "properties" in prop:
            for sub_prop in prop["properties"]:
                if "value" in sub_prop:
                    flatten_dict[".".join([prop["id"], sub_prop["id"]])] = sub_prop["value"]

    return flatten_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    spec_dict = {}
    for filepath in glob.glob(os.path.join(plugin_dir, "*.json")):
        with open(filepath) as f:
            plugin_spec = json.load(f)
            for key, value in plugin_spec.items():
                if key not in spec_dict:
                    spec_dict[key] = value
                elif isinstance(value, dict):
                    for subkey, subvalue in value.items():
                        if subkey not in spec_dict[key]:
                            spec_dict[key][subkey] = subvalue
                elif isinstance(value, list):
                    for item in value:
                        if isinstance(item, dict):
                            for subkey, subvalue in item.items():
                                if subkey not in spec_dict[key]:
                                    spec_dict[key][subkey] = subvalue
    return spec_dict

